import {pastPrint} from '../../web-bank/past-print.js';
import {replacementPopup} from '../../web-bank/question-replacement.js';
import {loadingTask} from '../../web-bank/loading-task.js';
import {questionContent} from '../../web-bank/print-question.js';
import {mathText} from '../../web-bank/math-text.js';
import {exportPdf} from '../../web-bank/web-export.js';
const node=(t,s='',c='')=>{const n=document.createElement(t);n.textContent=s;n.className=c;return n;},root=document.querySelector('main');
const action=(t,f)=>{const b=node('button',t);b.onclick=async()=>{try{await f();}catch(e){window.errors.push(e.message);}};return b;};
const field=(p,t,v='',type='text')=>{const l=node('label',t),i=node('input');i.type=type;i.value=v;l.append(i);p.append(l);return i;};
window.errors=[];window.calls=[];window.renderCalls=[];window.saved=null;
const sources=[2025,2024].map(year=>({source_id:'source-'+year,source:{academicYear:year,school:'시험중',grade:'중2',semester:'2학기',exam:'중간고사'},question_count:2}));
const cats=Array.from({length:4},(_,i)=>({question_id:'q'+i,revision_id:'r'+i,metadata:{source:{school:'시험중',documentId:sources[Math.floor(i/2)].source_id,academicYear:sources[Math.floor(i/2)].source.academicYear,originalNumber:String(i%2+1),semester:'2학기',exam:'중간고사'},classification:{primaryUnit:{id:'m2-8.7'}}},content:{body:'RAW $\\angle ABC$'},tier:1,sameType:true,sameUnit:true}));
const reader={render:async(id,options={})=>{renderCalls.push({id,...options});const i=Number(id.slice(1)),img=node('img');img.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="150" height="70"><path d="M10 60L75 10L140 60Z" stroke="black" fill="none"/></svg>');const question={body:`문항 ${i+1}. $\\angle ABC=60^\\circ$인 삼각형에서 $\\overline{AB}$의 길이를 구하시오.`,answer:String(i+1),solution:`상세 풀이 ${i+1}. $x+1=${i+2}$이므로 $x=${i+1}$이다.`,choices:['1','2','3']},figures=[{id:'diagram',node:img}],element=questionContent(question,figures);if(window.longSolutions)question.solution=(question.solution+'\n').repeat(45);if(options.answers)element.append(node('h3','상세 풀이'),mathText(question.solution));await new Promise(r=>setTimeout(r,20));return {catalog:cats[i],question,element,figures};}};
const rpc=async(name,args)=>{calls.push({name,args});if(name==='bank_question_sets_get')return [];if(name==='bank_source_exams')return sources;if(name==='bank_source_questions')return cats.filter(c=>c.metadata.source.documentId===args.source_key);if(name==='bank_exam_save'){window.saved=structuredClone(args.doc);return {version:1};}if(name==='bank_replacement_page')return {items:cats.slice(1,3),total:2,baseCount:2,extraCount:0,version:'fixture'};throw Error(name);};
const ctx={root,node,action,field,rpc,reader,config:{spaceId:'fixture'},user:{id:'fixture'},navigate:()=>{},message:t=>window.message=t};
window.openPrint=async server=>{root.replaceChildren();await pastPrint({...ctx,server});};
window.openReplacement=async originalOnly=>{window.replaced=false;await replacementPopup({...ctx,item:{questionId:'q0',revisionId:'r0'},draft:{rules:{units:['m2-8.7']},items:[{questionId:'q0',revisionId:'r0'}]},originalsOnly:originalOnly,onReplace:()=>window.replaced=true});};
window.checkLoading=async fail=>{try{await loadingTask(ctx,'불러오는 중',async()=>{await new Promise(r=>setTimeout(r,200));if(fail)throw Error('fixture failure');});}catch(e){return e.message;}};
window.pdf=async part=>{const page=root.querySelectorAll('.past-print-viewport .exam-pages')[part],file=await exportPdf(page,'fixture-'+part,node('p'),{download:false,securityWatermark:'0042',questionCount:4,answerWatermarks:part===1});return Array.from(new Uint8Array(await file.blob.arrayBuffer()));};
await openPrint();window.ready=true;
